/*!50001 VIEW `view_dzien_projekty` AS select str_to_date(concat(`t`.`Rok`,' ',`t`.`tydzienRoku`,' ',(case `d`.`Dzien_tygodnia` when 'Poniedziałek' then 1 when 'Wtorek' then 2 when 'Środa' then 3 when 'Czwartek' then 4 when 'Piątek' then 5 when 'Sobota' then 6 when 'Niedziela' then 0 end)),'%x %v %w') AS `Data`,concat(`do`.`Imie`,' ',`do`.`Nazwisko`) AS `Pracownik`,concat(`pj`.`Marka`,' ',`pj`.`Nr_rejestracyjny`) AS `Pojazd`,`pr`.`NazwaKod_Projektu` AS `Projekt`,`dp`.`Godziny_przepracowane` AS `GodzinyPrzepracowane` from ((((((`dzien_projekty` `dp` join `dzien` `d` on((`dp`.`Dzien_idDzien` = `d`.`idDzien`))) join `tydzien` `t` on((`d`.`Tydzien_idTydzien` = `t`.`idTydzien`))) join `pracownik` `p` on((`t`.`Pracownik_idPracownik` = `p`.`idPracownik`))) join `dane_osobowe` `do` on((`p`.`FK_Dane_osobowe` = `do`.`idDane_osobowe`))) left join `pojazdy` `pj` on((`dp`.`Pojazdy_idPojazdy` = `pj`.`idPojazdy`))) join `projekty` `pr` on((`dp`.`Projekty_idProjekty` = `pr`.`idProjekty`))) where (`dp`.`Godziny_przepracowane` > 0) */;
